// 1) Thiết bị đang "ngắt kết nối" -> bỏ qua mọi lệnh
if (flow.get('esp_offline') === true) {
    node.status({fill:'grey', shape:'ring', text:'offline: bỏ lệnh'});
    return null;
}
// 2) Mô phỏng lỗi: 10% lệnh bị bỏ qua
if (Math.random() < 0.10) {
    node.status({fill:'red', shape:'ring', text:'bỏ qua lệnh (lỗi giả lập)'});
    return null;
}
const v = String(msg.payload).trim().toUpperCase();
if (v !== 'ON' && v !== 'OFF') return null;
node.status({fill:'green', shape:'dot', text:'nhận ' + msg.topic + '=' + v});
return { room: msg.topic.split('/')[1], value: v };

// Nếu bị ngắt kết nối trong lúc đang xử lý thì cũng không publish được
if (flow.get('esp_offline') === true) return null;
return { topic: 'lights/' + msg.room + '/state', payload: msg.value, qos: 1, retain: true };

const off = (msg.payload === true);
flow.set('esp_offline', off);
node.status({fill: off ? 'red' : 'green', shape: 'dot', text: off ? 'OFFLINE' : 'ONLINE'});
// Thiết bị thật sẽ dùng Last Will; ở đây ta publish thay cho nó (retain)
return { topic: 'devices/esp01/status', payload: off ? 'offline' : 'online', qos: 1, retain: true };

const v = String(msg.payload).trim().toUpperCase();
if (v !== 'ON' && v !== 'OFF') return null;
return { event: 'reported', room: msg.topic.split('/')[1], value: v };

const online = String(msg.payload).trim().toLowerCase() === 'online';
node.status({fill: online ? 'green' : 'red', shape: 'dot', text: online ? 'ONLINE' : 'OFFLINE'});
// output 1: chỉ khi online thì Shadow đẩy lại desired; output 2: hiển thị trên dashboard
return [ online ? { event: 'online' } : null, { payload: online ? 'Trực tuyến' : 'Ngoại tuyến' } ];

// ================= SHADOW / TWIN =================
// Tài liệu lưu trong flow context 'shadow':
// { desired:{room:ON|OFF}, reported:{room:ON|OFF}, version:n, lastUpdated:ISO,
//   meta:{room:{status:'synced'|'pending'|'error', retries, lastSent, lastSource, lastUserAt}} }
const ROOMS = ['living', 'kitchen', 'bedroom'];
const NAMES = { living: 'Đèn phòng khách', kitchen: 'Đèn nhà bếp', bedroom: 'Đèn phòng ngủ' };
const RESEND_MS = 5000;          // desired != reported quá 5 s thì gửi lại
const MAX_RETRY = 3;             // tối đa 3 lần gửi lại, sau đó đánh dấu "không phản hồi"
const DASH_PRIORITY_MS = 3000;   // Dashboard ưu tiên hơn trợ lý trong 3 s (đặt 0 = last-write-wins thuần)

const now = Date.now();
let sh = flow.get('shadow');
if (!sh) {
    sh = { desired: {}, reported: {}, version: 0, lastUpdated: null, meta: {} };
    ROOMS.forEach(r => {
        sh.desired[r] = null; sh.reported[r] = null;
        sh.meta[r] = { status: 'synced', retries: 0, lastSent: 0, lastSource: null, lastUserAt: 0 };
    });
}
const cmds = [], notes = [];
const touched = new Set();
const send = r => cmds.push({ topic: 'lights/' + r + '/command', payload: sh.desired[r], qos: 1, retain: false });
const bump = () => { sh.version++; sh.lastUpdated = new Date(now).toISOString(); };

switch (msg.event) {
    case 'user': {              // Dashboard hoặc trợ lý ảo đổi desired
        const r = msg.room, v = msg.value, src = msg.source || 'dashboard';
        if (!ROOMS.includes(r) || (v !== 'ON' && v !== 'OFF')) break;
        const m = sh.meta[r];
        if (src === 'assistant' && m.lastSource === 'dashboard' && sh.desired[r] !== v && (now - m.lastUserAt) < DASH_PRIORITY_MS) {
            node.warn('XUNG ĐỘT ' + r + ': bỏ lệnh trợ lý (' + v + '), Dashboard đang ưu tiên');
            node.status({ fill: 'yellow', shape: 'ring', text: 'xung đột ' + r + ': bỏ lệnh assistant' });
            break;
        }
        sh.desired[r] = v; m.lastSource = src; m.lastUserAt = now;
        m.retries = 0; m.lastSent = now; bump();
        if (sh.reported[r] === v) { m.status = 'synced'; }
        else { m.status = 'pending'; send(r); }
        touched.add(r);
        break;
    }
    case 'reported': {          // thiết bị báo trạng thái thực tế
        const r = msg.room, v = msg.value;
        if (!ROOMS.includes(r)) break;
        const m = sh.meta[r];
        if (sh.reported[r] !== v) { sh.reported[r] = v; bump(); }
        if (sh.desired[r] === null) { sh.desired[r] = v; }          // khởi tạo từ state retain
        if (sh.desired[r] === v) { m.status = 'synced'; m.retries = 0; }
        else if (m.status === 'synced') { m.status = 'pending'; m.retries = 0; m.lastSent = now; }
        touched.add(r);
        break;
    }
    case 'online': {            // thiết bị online lại -> đẩy desired mới nhất xuống
        ROOMS.forEach(r => {
            if (sh.desired[r] === null) return;
            const m = sh.meta[r];
            m.retries = 0; m.lastSent = now;
            m.status = (sh.reported[r] === sh.desired[r]) ? 'synced' : 'pending';
            send(r); touched.add(r);
        });
        break;
    }
    case 'tick': {              // kiểm tra quá hạn mỗi giây
        ROOMS.forEach(r => {
            const m = sh.meta[r];
            if (sh.desired[r] === null || sh.desired[r] === sh.reported[r] || m.status === 'error') return;
            if (now - m.lastSent < RESEND_MS) return;
            if (m.retries < MAX_RETRY) {
                m.retries++; m.lastSent = now; send(r);
                node.status({ fill: 'yellow', shape: 'dot', text: 'gửi lại ' + r + ' lần ' + m.retries });
            } else {
                m.status = 'error'; touched.add(r);
                notes.push({ room: r, name: NAMES[r],
                    time: new Date(now).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false }) });
                node.status({ fill: 'red', shape: 'dot', text: r + ': không phản hồi' });
            }
        });
        const n = (context.get('ticks') || 0) + 1; context.set('ticks', n);
        if (n % 15 === 1) ROOMS.forEach(r => touched.add(r));       // làm tươi dashboard định kỳ
        break;
    }
}
flow.set('shadow', sh);

const ui = [...touched].map(r => ({ room: r, desired: sh.desired[r], reported: sh.reported[r], status: sh.meta[r].status }));
const snap = (touched.size > 0 || cmds.length > 0) ? { payload: JSON.parse(JSON.stringify(sh)) } : null;
return [cmds.length ? cmds : null, ui.length ? ui : null, notes.length ? notes : null, snap];

// output = phòng*3 + {0: switch(desired), 1: led(reported), 2: text(trạng thái)}
const idx = { living: 0, kitchen: 1, bedroom: 2 }[msg.room];
const text = { synced: 'Đã đồng bộ', pending: 'Đang chờ', error: 'Lỗi' }[msg.status];
const out = new Array(9).fill(null);
out[idx*3 + 0] = { payload: msg.desired !== null ? msg.desired : (msg.reported !== null ? msg.reported : 'OFF') };
out[idx*3 + 1] = { payload: msg.reported === 'ON' };
out[idx*3 + 2] = { payload: text };
return out;

// Token lấy từ biến môi trường ASSISTANT_TOKEN, mặc định để test
const TOKEN = env.get('ASSISTANT_TOKEN') || 'smarthome-secret-token';
const ROOMS = ['living', 'kitchen', 'bedroom'];
const reply = (code, body) => { msg.statusCode = code; msg.payload = body; return [null, msg]; };

// 1) Kiểm tra token trước -> 401
const auth = (msg.req.headers['authorization'] || '').trim();
if (auth !== 'Bearer ' + TOKEN) return reply(401, { error: 'unauthorized' });

// 2) Kiểm tra JSON -> 400
let body = msg.payload;
if (Buffer.isBuffer(body)) body = body.toString('utf8');
if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { return reply(400, { error: 'invalid JSON' }); }
}
if (!body || typeof body !== 'object' || !ROOMS.includes(body.device) ||
    !['on', 'off'].includes(String(body.action).toLowerCase())) {
    return reply(400, { error: 'body phải là {"device": living|kitchen|bedroom, "action": on|off}' });
}

// 3) Hợp lệ -> 200 và chuyển lệnh cho Shadow (nguồn = assistant)
msg.statusCode = 200;
msg.payload = { status: 'accepted', device: body.device, action: String(body.action).toLowerCase() };
const toShadow = { event: 'user', room: body.device, value: String(body.action).toUpperCase(), source: 'assistant' };
return [toShadow, msg];
